 const q=await f.queue();await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_event_policy');await f.pg.exec('SAVEPOINT hostile');await assert.rejects(f.pg.query("INSERT INTO public.report_job_issues(academy_id,id,job_id,kind,reason_code) VALUES($1,$2,$3,'failed','FORGED')",[f.a,randomUUID(),q.body.data.id]),/REPORT_JOB_ISSUE_STATE_REQUIRED/);await f.pg.exec('ROLLBACK TO SAVEPOINT hostile');}finally{await f.pg.exec('ROLLBACK');}await freshJobLogin(f);assert.equal((await f.work()).outcome,'cancelled');const e=(await f.pg.query<{event_id:string}>("SELECT event_id FROM public.automation_event_sources WHERE source_kind='report_job'")).rows[0];await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_event_policy');await f.pg.exec('SAVEPOINT actor');await assert.rejects(f.pg.query("INSERT INTO public.automation_event_sources(academy_id,event_id,audit_id,approval_id,source_kind,source_version,event_type,hub_id,occurred_at,projection,report_job_issue_id) SELECT academy_id,event_id,audit_id,approval_id,source_kind,source_version,event_type,hub_id,occurred_at,projection||jsonb_build_object('actorKind','human'),report_job_issue_id FROM public.automation_event_sources WHERE event_id=$1",[e.event_id]),/REPORT_JOB_ISSUE_SOURCE_REQUIRED/);await f.pg.exec('ROLLBACK TO SAVEPOINT actor');}finally{await f.pg.exec('ROLLBACK');}
